// The Mantia set is printed in its own full colour, so nothing retints — but
// full-luminance white stock glares on a dark table. Dark mode lays a warm
// scrim over the whole card: the paper drops to soft parchment, the colours
// dim in proportion, and the print's own contrast order stays intact.
export function hanaSVG(id, { dark = false } = {}) {
  const body = id === 'back' ? BACK : CARDS[id];
  const scrim = dark ? '<rect width="976" height="1600" fill="#140F08" opacity="0.2"/>' : '';
  return '<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 976 1600">' + body + scrim + '</svg>';
}
